const followups = $input.all()[0].json;
const dormant = $input.all()[1].json;

let msg = '☀️ *J9-AiRE Daily Brief*\n\n';

if (followups.length > 0) {
  msg += `*Follow-ups due today (${followups.length}):*\n`;
  followups.forEach(c => {
    msg += `• ${c.first_name} ${c.last_name} — last contact: ${c.last_contact_date || 'never'}\n`;
  });
} else {
  msg += '*No follow-ups due today* ✓\n';
}

msg += '\n';

if (dormant.length > 0) {
  msg += `*⚠️ Dormant clients (60+ days, ${dormant.length}):*\n`;
  dormant.slice(0, 10).forEach(c => {
    msg += `• ${c.first_name} ${c.last_name} — last contact: ${c.last_contact_date}\n`;
  });
}

return [{ json: { text: msg } }];
